package com.idark.valoria.core.recipe;import com.idark.valoria.*;import com.idark.valoria.registries.block.types.*;import com.mojang.serialization.*;import com.mojang.serialization.codecs.*;import net.minecraft.core.*;import net.minecraft.network.*;import net.minecraft.network.codec.*;import net.minecraft.resources.*;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.*;public class HeavyAnvilRecipe implements Recipe<ContainerRecipeInput>{    private final Ingredient input;    private final ItemStack result;    private final int requiredHits;    private final int maxInstability;    private final float cursorSpeed;    private final HeavyAnvilTier minTier;    private final boolean acceptsTierBonus;    private ResourceLocation id;    public HeavyAnvilRecipe(Ingredient input, ItemStack result, int requiredHits, int maxInstability, float cursorSpeed, HeavyAnvilTier minTier, boolean acceptsTierBonus){        this.input = input;        this.result = result;        this.requiredHits = requiredHits;        this.maxInstability = maxInstability;        this.cursorSpeed = cursorSpeed;        this.minTier = minTier != null ? minTier : HeavyAnvilTier.BRONZE;        this.acceptsTierBonus = acceptsTierBonus;    }    public HeavyAnvilRecipe(Ingredient input, ItemStack result, int requiredHits, int maxInstability, float cursorSpeed){        this(input, result, requiredHits, maxInstability, cursorSpeed, HeavyAnvilTier.BRONZE, true);    }    @Override    public boolean matches(ContainerRecipeInput pContainer, Level pLevel){        if(pLevel.isClientSide()){            return false;        }        return input.test(pContainer.getItem(0));    }    @Override    public ItemStack assemble(ContainerRecipeInput pContainer, HolderLookup.Provider pRegistryAccess){        return this.result.copy();    }    @Override    public boolean canCraftInDimensions(int pWidth, int pHeight){        return true;    }    @Override    public boolean isSpecial(){        return true;    }    @Override    public ItemStack getResultItem(HolderLookup.Provider pRegistryAccess){        return this.result.copy();    }    @Override    public NonNullList<Ingredient> getIngredients(){        return NonNullList.of(Ingredient.EMPTY, this.input);    }    public HeavyAnvilRecipe withId(ResourceLocation id){        this.id = id;        return this;    }    public ResourceLocation getId(){        return this.id;    }    public int getRequiredHits(){        return this.requiredHits;    }    public int getMaxInstability(){        return this.maxInstability;    }    public float getCursorSpeed(){        return this.cursorSpeed;    }    public HeavyAnvilTier getMinTier(){        return this.minTier;    }    public boolean acceptsTierBonus(){        return this.acceptsTierBonus;    }    @Override    public RecipeSerializer<?> getSerializer(){        return Serializer.INSTANCE;    }    @Override    public RecipeType<?> getType(){        return Type.INSTANCE;    }    public static class Type implements RecipeType<HeavyAnvilRecipe>{        public static final Type INSTANCE = new Type();        public static final String ID = "heavy_anvil";    }    public static class Serializer implements RecipeSerializer<HeavyAnvilRecipe>{        public static final HeavyAnvilRecipe.Serializer INSTANCE = new HeavyAnvilRecipe.Serializer();        public static final ResourceLocation ID = Valoria.loc("heavy_anvil");        private static final MapCodec<HeavyAnvilRecipe> CODEC = RecordCodecBuilder.mapCodec(i -> i.group(            Ingredient.CODEC.fieldOf("ingredient").forGetter(r -> r.input),            RecipeCodecs.ITEM_STACK.fieldOf("result").forGetter(r -> r.result),            Codec.INT.optionalFieldOf("required_hits", 10).forGetter(r -> r.requiredHits),            Codec.INT.optionalFieldOf("max_instability", 3).forGetter(r -> r.maxInstability),            Codec.FLOAT.optionalFieldOf("cursor_speed", 0.05f).forGetter(r -> r.cursorSpeed),            HeavyAnvilTier.CODEC.optionalFieldOf("min_tier", HeavyAnvilTier.BRONZE).forGetter(r -> r.minTier),            Codec.BOOL.optionalFieldOf("accepts_tier_bonus", true).forGetter(r -> r.acceptsTierBonus)).apply(i, HeavyAnvilRecipe::new));        private static final StreamCodec<RegistryFriendlyByteBuf, HeavyAnvilRecipe> STREAM_CODEC = StreamCodec.of((buf, recipe) -> encode(recipe, buf), Serializer::decode);        public static void encode(HeavyAnvilRecipe recipe, RegistryFriendlyByteBuf buf){            Ingredient.CONTENTS_STREAM_CODEC.encode(buf, recipe.input);            ItemStack.STREAM_CODEC.encode(buf, recipe.result);            ByteBufCodecs.VAR_INT.encode(buf, recipe.requiredHits);            ByteBufCodecs.VAR_INT.encode(buf, recipe.maxInstability);            ByteBufCodecs.FLOAT.encode(buf, recipe.cursorSpeed);            ByteBufCodecs.fromCodec(HeavyAnvilTier.CODEC).encode(buf, recipe.minTier);            ByteBufCodecs.BOOL.encode(buf, recipe.acceptsTierBonus);        }        public static HeavyAnvilRecipe decode(RegistryFriendlyByteBuf buf){            Ingredient input = Ingredient.CONTENTS_STREAM_CODEC.decode(buf);            ItemStack result = ItemStack.STREAM_CODEC.decode(buf);            int requiredHits = ByteBufCodecs.VAR_INT.decode(buf);            int maxInstability = ByteBufCodecs.VAR_INT.decode(buf);            float cursorSpeed = ByteBufCodecs.FLOAT.decode(buf);            HeavyAnvilTier minTier = ByteBufCodecs.fromCodec(HeavyAnvilTier.CODEC).decode(buf);            boolean acceptsTierBonus = ByteBufCodecs.BOOL.decode(buf);            return new HeavyAnvilRecipe(input, result, requiredHits, maxInstability, cursorSpeed, minTier, acceptsTierBonus);        }        @Override        public MapCodec<HeavyAnvilRecipe> codec(){            return CODEC;        }        @Override        public StreamCodec<RegistryFriendlyByteBuf, HeavyAnvilRecipe> streamCodec(){            return STREAM_CODEC;        }    }}